-- WardVault Clinical Database Export (PostgreSQL compatible)

DROP TABLE IF EXISTS clinical_notes CASCADE;
DROP TABLE IF EXISTS active_shifts CASCADE;
DROP TABLE IF EXISTS patients CASCADE;
DROP TABLE IF EXISTS providers CASCADE;

CREATE TABLE providers (id VARCHAR(100) PRIMARY KEY, organization VARCHAR(100), name VARCHAR(255), speciality VARCHAR(100), password_hash VARCHAR(255));
CREATE TABLE patients (id VARCHAR(100) PRIMARY KEY, first VARCHAR(100), last VARCHAR(100), name VARCHAR(255), age INT, gender VARCHAR(10), organization VARCHAR(100), ward_id VARCHAR(100), condition TEXT);
CREATE TABLE active_shifts (id SERIAL PRIMARY KEY, provider_id VARCHAR(100), ward_id VARCHAR(100), is_active BOOLEAN);
CREATE TABLE clinical_notes (id SERIAL PRIMARY KEY, patient_id VARCHAR(100), provider_id VARCHAR(100), note_text TEXT, timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP, correction_reason TEXT, supersedes_note_id INT);

